// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/health", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/instance", wrapper.GetInstance)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/signup", wrapper.Signup)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/totp/verify", wrapper.VerifyTotp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/totp/enroll", wrapper.EnrollTotp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/totp/confirm", wrapper.ConfirmTotp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/refresh", wrapper.RefreshTokens)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/sessions", wrapper.ListMySessions)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/me/sessions/{sessionId}", wrapper.RevokeMySession)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/library", wrapper.ListLibrary)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/books/{bookId}", wrapper.GetBook)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/me/library/{bookId}", wrapper.RemoveFromMyLibrary)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/me/library/{bookId}/restore", wrapper.RestoreToMyLibrary)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/me/library/{bookId}/hide", wrapper.HideInMyLibrary)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/authors/{personId}", wrapper.GetAuthor)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/narrators/{personId}", wrapper.GetNarrator)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/series/{seriesId}", wrapper.GetSeries)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/progress/{bookId}", wrapper.GetProgress)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/me/progress/{bookId}", wrapper.PutProgress)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/sync", wrapper.GetSyncDelta)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/books/{bookId}/files/{fileId}", wrapper.GetBookFile)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/stream/{bookId}/hls/{profile}/index.m3u8", wrapper.GetHlsPlaylist)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/stream/{bookId}/hls/{profile}/{segment}", wrapper.GetHlsSegment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/books/{bookId}/stream-url", wrapper.CreateStreamUrl)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/books/{bookId}/cover", wrapper.GetBookCover)
	})

	return r
}

